class Solution {
    int gcd(int a,int b) {while(b){int t=a%b;a=b;b=t;}return a;}
public:
    int minimumSplits(vector<int>& nums) {
        int groups=1, g=nums[0];
        for (int i=1;i<(int)nums.size();++i) {
            int next=gcd(g,nums[i]);
            if (next==1) {++groups;g=nums[i];}
            else g=next;
        }
        return groups;
    }
};
